SELECT * FROM investment_transaction
WHERE user_id = #{userId}
AND trade_date >= #{from}
AND trade_date <= #{to}
AND txn_type = #{txnType}
AND account_id = #{accountId}
AND holding_id = #{holdingId}
ORDER BY trade_date DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM investment_transaction
WHERE user_id = #{userId}
AND trade_date >= #{from}
AND trade_date <= #{to}
AND txn_type = #{txnType}
AND account_id = #{accountId}
AND holding_id = #{holdingId}
